using System.Security.Claims; using HelpDeskPro.Api.Data; using HelpDeskPro.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace HelpDeskPro.Api.Controllers;
[ApiController][Route("api/tickets/{ticketId}/attachments")][Authorize]
public class AttachmentsController:ControllerBase { readonly AppDbContext db; readonly IWebHostEnvironment env; public AttachmentsController(AppDbContext db,IWebHostEnvironment env){this.db=db;this.env=env;}
[HttpGet] public async Task<IActionResult> Get(int ticketId)=>Ok(await db.TicketAttachments.Where(x=>x.TicketId==ticketId).OrderByDescending(x=>x.CreatedAt).Select(x=>new{x.Id,x.FileName,x.ContentType,x.Size,x.CreatedAt}).ToListAsync());
[HttpPost] [RequestSizeLimit(20_000_000)] public async Task<IActionResult> Upload(int ticketId,IFormFile file){if(file==null||file.Length==0)return BadRequest("File is required");var ticket=await db.Tickets.FindAsync(ticketId);if(ticket==null)return NotFound();var folder=Path.Combine(env.ContentRootPath,"uploads");Directory.CreateDirectory(folder);var stored=Guid.NewGuid()+Path.GetExtension(file.FileName);await using var s=System.IO.File.Create(Path.Combine(folder,stored));await file.CopyToAsync(s);var a=new TicketAttachment{TicketId=ticketId,FileName=Path.GetFileName(file.FileName),StoredName=stored,ContentType=file.ContentType,Size=file.Length,UploadedById=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!)};db.TicketAttachments.Add(a);await db.SaveChangesAsync();return Ok(new{a.Id,a.FileName,a.ContentType,a.Size,a.CreatedAt});}
[HttpGet("{id}/download")] public async Task<IActionResult> Download(int ticketId,int id){var a=await db.TicketAttachments.FirstOrDefaultAsync(x=>x.Id==id&&x.TicketId==ticketId);if(a==null)return NotFound();var path=Path.Combine(env.ContentRootPath,"uploads",a.StoredName);if(!System.IO.File.Exists(path))return NotFound();return PhysicalFile(path,a.ContentType,a.FileName);}}
